INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('scp-1936','▼','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"scp-1936","name":"▼","team":"demon","ability":"Each night*, choose a player: they die. [1 to All Minions are from the Trouble Brewing set]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1936 is the town of Daleport which fell to a series of destructive events ushered in by a ritual attempting to bring gods into our world.","summaryBullets":["If the ▼ is to be in-play, one to all of the Minions will instead be using characters from the Trouble Brewing set.","Minions from the Trouble Brewing set do not have to be included on the script for this Demon.","The Trouble Brewing set of Minions are the Baron, Poisoner, Scarlet Woman, and Spy.","There may be duplicates of Trouble Brewing Minions only if those respective Minions are already present on the script.","Jinxes between on-script characters and Trouble Brewing Minions will instead be facilitated as jinxes on the ▼.","When using a scripting tool to create the .JSON of characters, you may include all Trouble Brewing Minions if this Demon is present and note which ones are locked behind the ▼''s setup effect, or use the ▼''s Minion JSONs down below this page."],"howToRun":["While setting up the game, before putting character tokens in the bag, replace at least one Minion character token with a Minion character token from the Trouble Brewing set/edition.","Each night except the first, wake the ▼. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the ▼ to sleep."],"iconBy":"le_nuberto","jinxes":[{"name":"Damsel","align":"good","text":"If the Spy is (or has been) in play, the Damsel is poisoned.","id":"damsel"},{"name":"Hatter","align":"good","text":"When the Hatter''s ability activates, if the Demon chooses to be the ▼, Minions learn this and can be Trouble Brewing Minions.","id":"hatter"},{"name":"Heretic","align":"good","text":"The Spy and Heretic cannot both be in-play at the same time. The Baron might only add 1 Outsider, not 2.","id":"heretic"},{"name":"Magician","align":"good","text":"When the Spy sees the Grimoire, the Demon and Magician''s character tokens are removed.","id":"magician"},{"name":"Ogre","align":"good","text":"The Spy registers as evil to the Ogre.","id":"ogre"},{"name":"Pit-Hag","align":"evil","text":"If the ▼ is not in-play, the Pit-Hag cannot create the Poisoner, Spy, Baron, or Scarlet Woman if they are only available by the ▼.","id":"pithag"},{"name":"Plague Doctor","align":"good","text":"If the ▼ is not in-play, the Poisoner, Spy, Baron, or Scarlet Woman abilities cannot be brought in if they are only available by the ▼. If the Plague Doctor dies, a living Minion gains the Spy or Scarlet Woman ability in addition to their own ability, and learns this. If the Storyteller gains the Baron ability, up to two players become not-in-play Outsiders.","id":"plaguedoctor"},{"name":"Poppy Grower","align":"good","text":"If the Poppy Grower is in play, the Spy does not see the Grimoire until the Poppy Grower dies.","id":"poppygrower"},{"name":"Hangman","align":"good","text":"The ▼ is not an earthly name with a usable letter.","slug":"hangman-scp-fragmented-veil"},{"name":"Wig Snatcher","align":"good","text":"The Wig Snatcher cannot become the Spy.","id":"wigsnatcher_hblreleased"},{"name":"Visionary","align":"evil","text":"The Spy and Visionary cannot both be in-play at the same time.","id":"visionary_the_bootleggers_anthology"},{"name":"Ornithologist","align":"good","text":"If the Ornithologist is in-play, the Spy does not see the Grimoire until they die.","id":"ornithologist_2tfafullcharacterlist"}],"customBoxes":[{"title":"In the almanac JSON","content":"**Other nights:** The ▽ points to a player. That player dies."},{"title":"▼ Minions JSON","content":"This is the JSON for Minions obliged to only spawn if the ▼ is to be the Demon.\n\n**Poisoner-▼** (Minion)\nEach night, choose a player: they are poisoned until dusk. [▼ is the Demon]\n\n**First night:** The Poisoner points to a player. That player is poisoned.\n**Other nights:** The previously poisoned player is no longer poisoned. The Poisoner points to a player. That player is poisoned.\n**Reminders:** Poisoned\n**Setup:** yes\n\n**Baron-▼** (Minion)\n[+2 Outsiders. ▼ is the Demon]\n\n**Setup:** yes\n\n**Scarlet Woman-▼** (Minion)\nIf 5+ players live (travellers don''t count.) & the Demon dies, you become the Demon. [▼ is the Demon]\n\n**Other nights:** If the Scarlet Woman became the Demon today: Show the ''You are'' card, then the demon token.\n**Reminders:** Is The Demon\n**Setup:** yes\n\n**Spy-▼** (Minion)\nEach night, you see the Grimoire. You might register as good & as a Townsfolk or Outsider, even if dead. [▼ is the Demon]\n\n**First night:** Show the Grimoire to the Spy for as long as they need.\n**Other nights:** Show the Grimoire to the Spy for as long as they need.\n**Setup:** yes"}],"firstNight":0,"otherNight":36.1936,"reminders":["Dead"],"setup":true,"otherNightReminder":"The ▼ points to a player. That player dies.","art":"art/scp-1936.png","jsonId":"1_scp_fragmented_veil","curata":false}','scp-fragmented-veil/scp-1936','published',datetime('now'),datetime('now')),
('eyeceue','Eyeceue','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"eyeceue","name":"Eyeceue","team":"demon","ability":"A living known Minion ''is the Demon'' & chooses a player each night*: they die. If there are ≤2 living good & an evil died today, no good dies tonight. [+1 no-info Minion]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1981 is an archived video tape of Ronald Reagan''s ''Evil Empire'' speech that deviates into madness & absurdity over multiple re-runs.","summaryBullets":["Whilst a Minion breathes air, there is always an active ''Demon'' that upholds the evil team.","However, the evil team''s line-up of 1 to 3 Minions + 1 Demon will be replaced with 1 to 3 Minions + 1 Minion that isn''t a part of the evil team info.","That ''Demon'' is a random living Minion known in the evil team until their death, continuing until there are no living Minions left to stand.","This does not include the +1 Minion not a part of the evil team info replaced by this ability or any other miscellaneous evil players.","In layman''s terms, for good to win, the known evil team must be completely eradicated as they can pick off someone each night.","The Eyeceue isn''t actually an active character that can be affected, killed, poisoned, etc. This is a non-playable character, similar to Lil'' Monsta.","At the same time, players using the ''Eyeceue'' kill command aren''t actually \"using their ability.\" for it.","Any kills made against good players won''t occur under the conditions that there are two or less good players alive, and an evil player died today.","This affects not just the Demon''s kills, but all other kills that can occur tonight, including those that occur after any deaths that would''ve activated the condition."],"howToRun":["While setting up the game, before putting character tokens in the bag, remove the Eyeceue''s token and add a Minion character token. Add the Eyeceue''s **IS THE DEMON** and **BLIND** reminder token to the Grimoire.","At the start of the first night, move the **BLIND** reminder token to any Minion player. Do not do the Minion Info/Demon Info steps for this player, and do not include them in said steps for other players.","At all times after passing out character tokens, place the **IS THE DEMON** reminder token by a living Minion player''s character token who doesn''t have the **BLIND** reminder token - when they die and there is at-least 1 more living Minion player that satisfies this condition, move the reminder token to their character token, otherwise, the evil team loses.","If an evil player dies during the day, mark them with the **DIED TODAY** reminder.","Each night except the first, if there are 3 or more alive good players or no evil player is marked **DIED TODAY**, wake ''the Demon'' player, show them the **THIS CHARACTER SELECTED YOU** info token, then the Eyeceue''s token. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the Eyeceue to sleep.","During the night, if a good player would die but there are 2 or less alive good players and an evil player is marked **DIED TODAY**, they don''t.","At dawn, remove the **DIED TODAY** reminder token if it is present."],"tips":["Feel free to end the game prematurely in the scenario that the good team are left in a position in which they cannot win, that typically being when only 1 good player is left, thus they are unable to eliminate the evil team without reaching a stand-off of exactly 2 players.","**Optional rule:** Travellers do not register as living good players to the Eyeceue''s ability. This is to prevent the catch-up mechanic of the Eyeceue from being disabled with Travellers in the game, and is the intended design of this character."],"iconBy":"le_nuberto","jinxes":[{"name":"Assassin","align":"evil","text":"The Assassin''s kill cannot penetrate the death-prevention of the Eyeceue''s ability.","id":"assassin"},{"name":"Boomdandy","align":"evil","text":"If the Eyeceue is active, the Boomdandy is always the last player to be ''the Demon'', and their ability isn''t active.","id":"boomdandy"},{"name":"Exorcist","align":"good","text":"If the Exorcist chooses ''the Demon'', ''the Demon'' loses their ability until dusk and does not wake to kill tonight, instead learning the Exorcist player.","id":"exorcist"},{"name":"Fortune Teller","align":"good","text":"If the Eyeceue is active, there is no ''Red Herring'' for the Fortune Teller (unless otherwise.)","id":"fortuneteller"},{"name":"Goblin","align":"evil","text":"If the Eyeceue is active, the Goblin is always the last player to be ''the Demon'', and their ability isn''t active.","id":"goblin"},{"name":"Lycanthrope","align":"good","text":"If the Lycanthrope rampages a good player, ''the Demon'' still wakes for their Minion ability but does not wake to kill tonight.","id":"lycanthrope"},{"name":"Magician","align":"good","text":"The Magician instead makes Minions think they are another Minion.","id":"magician"},{"name":"Mastermind","align":"evil","text":"If the Eyeceue is active, the Mastermind is always the last player to be ''the Demon'', and their ability is active when they die.","id":"mastermind"},{"name":"Scarlet Woman","align":"evil","text":"The Scarlet Woman is always the blind Minion. When the last Minion dies, they become it and are no longer considered blind.","id":"scarletwoman"},{"name":"Summoner","align":"evil","text":"The Summoner instead removes a Minion instead of the Demon, and also creates an evil Minion instead of an evil Demon. The Eyeceue is assigned to no-one until the Summoner makes their Minion. If the Minion chosen is already in-play, an out-of-play Minion is chosen instead.","id":"summoner"},{"name":"Spy","align":"evil","text":"If the Eyeceue is active, the Spy only sees half of the Grimoire & cannot be the blind Minion.","id":"spy"},{"name":"Vizier","align":"evil","text":"If the Eyeceue is active, the Vizier cannot be ''the Demon'' & cannot be the blind Minion.","id":"vizier"},{"name":"Widow","align":"evil","text":"If the Eyeceue is active, the Widow only sees half of the Grimoire & cannot be the blind Minion.","id":"widow"},{"name":"Neglected","align":"good","text":"If ''the Demon'' chooses to kill a Neglected-chosen player, they can be made drunk despite it not being their ability.","slug":"neglected"},{"name":"GOC Physics","align":"good","text":"If ''the Demon'' chooses to kill the actived GOC Physics, they can still be affected despite it not being their ability and being ''the Demon''.","slug":"goc-physics"},{"name":"Peanut","align":"evil","text":"The Peanut''s kill cannot penetrate the death-prevention of the Eyeceue''s ability.","slug":"peanut"},{"name":"Antipath","align":"evil","text":"If the Eyeceue is active, the Antipath is the blind Minion.","slug":"antipath"},{"name":"Prosecutor","align":"evil","text":"The Prosecutor''s kill cannot penetrate the death-prevention of the Eyeceue''s ability.","slug":"prosecutor-scp-fragmented-veil"},{"name":"Esper","align":"evil","text":"If the Eyeceue is active, the Esper only sees half of the Grimoire & cannot be the blind Minion.","id":"esper_the_bootleggers_anthology"},{"name":"Surgeon","align":"evil","text":"The Surgeon can kill ''the Demon''.","id":"surgeon_the_bootleggers_anthology"},{"name":"Gargoyle","align":"evil","text":"If the Eyeceue is active, the Gargoyle is always the last player to be ''the Demon'', and their ability isn''t active.","id":"gargoyle"},{"name":"Vigilante","align":"good","text":"The Vigilante can kill ''the Demon''.","id":"vigilante_hypers_hoard_of_homebrew"},{"name":"Bloodless","align":"evil","text":"If the Eyeceue is active, the 1st Minion that dies registers as the Demon to the Bloodless. They only see half the Grimore unless they are the blind Minion. If good or no-one is executed, they become their character.","id":"bloodless_darkartists_stuff"}],"customBoxes":[{"title":"Alternative JSON & How to Run","content":"If you want a bit more of a balanced version that is less wordy but doesn''t resemble the original gameplay of it''s TOS inspiration. This changes the Minion not a part of the evil team info to an evil Townsfolk who also isn''t a part of the evil team info due to not being a Minion. Additionally, all evil players are to be the Demon this game, instead of excluding the player not known to the evil team, which can also go to evil Outsiders (until they stop becoming evil).\n\nWhile setting up the game, before putting character tokens in the bag, remove the Eyeceue''s token and add a Townsfolk character token. Add the Eyeceue''s IS THE DEMON reminder token to the Grimoire.\n\nWhile preparing the first night, choose a Townsfolk character and turn their character token upside down (this shows they are now evil.)\n\nAt the start of the first night, wake the chosen Townsfolk. Show the YOU ARE info token then give a thumbs down. Put them to sleep.\n\nAt all times after passing out character tokens, place the **IS THE DEMON** reminder token by a living evil player''s character token - when they die and there is at-least 1 more living evil player, move the reminder token to their character token, otherwise, the evil team loses.\n\nIf an evil player dies during the day, mark them with the DIED TODAY reminder.\n\nEach night except the first, if there are 3 or more alive good players or no evil player is markedDIED TODAY, wake ''the Demon'' player, show them the THIS CHARACTER SELECTED YOU info token, then the Eyeceue''s token. They point at any player. That player dies - mark them with the DEAD reminder. Put the Eyeceue to sleep.\n\nDuring the night, if a good player would die but there are 2 or less alive good players and an evil player is marked DIED TODAY, they don''t.\n\nAt dawn, remove the DIED TODAY reminder token if it is present.\n\n**Eyeceue █~** (Demon)\nA living evil ''is the Demon'' & chooses a player each night*: they die. If there are ≤2 living good & an evil died today, no good dies tonight. [+1 evil Townsfolk]\n\n**First night:** Wake the townsfolk who is evil and show them the ''You are'' card and the thumbs down evil sign.\n**Other nights:** Wake the Demon, show them the ''This character selected you'' token, then the Eyeceue''s token. They point to a player. That player dies unless both there are 2 or less good players alive and an evil player died today.\n**Reminders:** Is the demon, Died today, Dead\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nAssassin: The Assassin''s kill cannot penetrate the death-prevention of the Eyeceue''s ability.\nBoomdandy: If the Eyeceue is active, the Boomdandy is always the last player to be ''the Demon'', and their ability isn''t active.\nExorcist: If the Exorcist chooses ''the Demon'', ''the Demon'' loses their ability until dusk and does not wake to kill tonight, instead learning the Exorcist player.\nGoblin: If the Eyeceue is active, the Goblin is always the last player to be ''the Demon'', and their ability isn''t active.\nLycanthrope: If the Lycanthrope rampages a good player, ''the Demon'' still wakes for their Minion ability but does not wake to kill tonight.\nMagician: The Magician instead makes Minions think they are another Minion.\nMastermind: If the Eyeceue is active, the Mastermind is always the last player to be ''the Demon'', and their ability is active when they die.\nScarlet Woman: The Scarlet Woman registers the evil Townsfolk as ''the Demon''.\nSummoner: The Summoner instead removes a Minion instead of the Demon, and also creates an evil Minion instead of an evil Demon. The Eyeceue is assigned to no-one until the Summoner makes their Minion. If the Minion chosen is already in-play, an out-of-play Minion is chosen instead.\nSpy: If the Eyeceue is active, the Spy only sees half of the Grimoire.\nVizier: If the Eyeceue is active, the Vizier cannot be ''the Demon''.\nWidow: If the Eyeceue is active, the Widow only sees half of the Grimoire.\nNeglected: If ''the Demon'' chooses to kill a Neglected-chosen player, they can be made drunk despite it not being their ability.\nGOC Physics: If ''the Demon'' chooses to kill the actived GOC Physics, they can still be affected despite it not being their ability and being ''the Demon''.\nPeanut: The Peanut''s kill cannot penetrate the death-prevention of the Eyeceue''s ability.\nProsecutor: The Prosecutor''s kill cannot penetrate the death-prevention of the Eyeceue''s ability.\nEsper: If the Eyeceue is active, the Esper only sees half of the Grimoire.\nSurgeon: The Surgeon can kill ''the Demon''.\nGargoyle: If the Eyeceue is active, the Gargoyle is always the last player to be ''the Demon'', and their ability isn''t active.\nVigilante: The Vigilante can kill ''the Demon''.\nBloodless: If the Eyeceue is active, the 1st Minion that dies registers as the Demon to the Bloodless. They only see half the Grimore. If good or no-one is executed, they become their character."}],"firstNight":0,"otherNight":49.1981,"remindersGlobal":["Is the demon","Blind","Died today","Dead"],"setup":true,"special":[{"name":"bag-disabled","type":"selection"}],"otherNightReminder":"Wake the Demon, show them the ''This character selected you'' token, then the Eyeceue''s token. They point to a player. That player dies unless both there are 2 or less good players alive and an evil player died today.","art":"art/eyeceue.png","jsonId":"eyeceue_scp_fragmented_veil","curata":false}','scp-fragmented-veil/eyeceue','published',datetime('now'),datetime('now'));
